import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Cephadm for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"Cephadm for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["Ceph","Cephadm","会议纪要","自动化","容器化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Cephadm_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/Cephadm_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),l={name:"posts/2026/Cephadm_for_Ceph_Developer_Summit_-_Vampire.md"};function i(d,e,n,s,h,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次 Ceph Developer Summit 的 Orchestration（orch）专题由 Adam King 主持（代替 Redouane），重点讨论了 Cephadm 在 Vampire 版本中的多项改进计划，包括性能优化、多架构支持、并行部署、容器化方向、开发测试环境、可观测性增强以及 SMB/NFS 协议支持等议题。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="_1-cephadm-主机操作性能优化" tabindex="-1">1. Cephadm 主机操作性能优化 <a class="header-anchor" href="#_1-cephadm-主机操作性能优化" aria-label="Permalink to &quot;1. Cephadm 主机操作性能优化&quot;">​</a></h3><p>当前 Cephadm 在每次服务循环（serve loop）中会在宿主机上执行若干元数据收集操作，主要包括：</p><ul><li><strong><code>cephadm ls</code></strong>：速度较慢，主要原因是需要启动容器并执行版本查询命令。在 agent 模式下已有初步缓存优化（container ID 未变化时跳过版本查询）。</li><li><strong><code>ceph-volume inventory</code></strong>：耗时较长，可考虑引入缓存机制，需与 ceph-volume 专家进一步沟通。</li><li><strong><code>gather facts</code></strong>：原本刷新频率为 60 秒/次，后续加入了 CPLD 等信息采集后变得很慢，需要拆分为多个子任务并设置不同的刷新周期。</li></ul><p><strong>目标</strong>：减少从执行 spec 到实际部署 daemon 之间的等待时间，计划在 Vampire 版本中推进相关优化。</p><h3 id="_2-多架构-multi-arch-镜像支持" tabindex="-1">2. 多架构（Multi-arch）镜像支持 <a class="header-anchor" href="#_2-多架构-multi-arch-镜像支持" aria-label="Permalink to &quot;2. 多架构（Multi-arch）镜像支持&quot;">​</a></h3><p><strong>问题背景</strong>：当集群中同时存在 x86 和 ARM 架构节点时，Cephadm 默认将镜像名转换为 digest（特定架构的摘要），导致跨架构拉取镜像失败。</p><p><strong>计划</strong>：</p><ul><li>在 <code>gather facts</code> 阶段采集宿主机的 CPU 架构信息。</li><li>在镜像信息展示命令中增加架构元数据字段。</li><li>处理 MonDB 中 <code>container_image</code> 配置项在多架构场景下的逻辑。</li><li>Vampire 目标：完成架构信息采集的初步实现，使混合架构集群无需手动关闭 <code>repo_digest</code> 选项即可正常运行。</li></ul><h3 id="_3-daemon-并行部署" tabindex="-1">3. Daemon 并行部署 <a class="header-anchor" href="#_3-daemon-并行部署" aria-label="Permalink to &quot;3. Daemon 并行部署&quot;">​</a></h3><p><strong>现状</strong>：Cephadm 当前在升级和应用 spec 时，均顺序逐个部署或移除 daemon，效率较低。</p><p><strong>计划</strong>：</p><ul><li>重构部署流程以支持并行操作。</li><li>分阶段推进：先完成部署逻辑重构，再启用并行触发，最终扩展到升级流程和依赖变更场景。</li><li>计划在 Vampire 版本早期合入，充分时间迭代修复 bug。</li><li>对大规模集群的部署效率提升显著。</li></ul><h3 id="_4-cephadm-容器化" tabindex="-1">4. Cephadm 容器化 <a class="header-anchor" href="#_4-cephadm-容器化" aria-label="Permalink to &quot;4. Cephadm 容器化&quot;">​</a></h3><p><strong>议题一：Cephadm 自身容器化</strong></p><p>Ernest 介绍了将 Cephadm 本身容器化的思路：</p><ul><li><strong>动机</strong>：Cephadm 目前是唯一未以容器形式发布的组件，且其 Python 版本受宿主机 OS 限制（如 RHEL 9 绑定 Python 3.9，已 EOL）。</li><li><strong>目标</strong>：解耦宿主机 OS 依赖，支持更新的 Python 版本及第三方库（如 Jinja），并通过 rootless 容器降低对宿主机的权限要求。</li><li><strong>难点</strong>：当前 Cephadm 通过 <code>systemctl</code> CLI 与 systemd 交互，需改为 D-Bus 接口；完整的 rootless 隔离需要较大重构，短期内可先以 privileged 容器方式获取依赖解耦收益。</li><li><strong>近期方向</strong>：先以 privileged 容器为基础实现依赖隔离，后续逐步缩减权限。</li></ul><p><strong>议题二：容器内运行 Ceph 集群（ceph-devstack / ceph-about）</strong></p><p>Nizam 介绍了在容器中运行由 Cephadm 部署的 Ceph 集群的实验性项目（称为 &quot;ceph-about&quot;）：</p><ul><li><strong>动机</strong>：在本地同时运行多个 Ceph 集群用于测试，基于 VM 的 VSTART 方式资源消耗大，不适合笔记本环境。</li><li><strong>实现方式</strong>：挂载 Podman socket 至容器内，使用 privileged 模式并覆盖部分 systemctl 行为，OSD 采用文件/目录挂载方式（非 LVM）。</li><li><strong>成果</strong>：在本地可启动 5-6 个健康的单节点集群，2 分钟内完成 bootstrap；通过 GitHub workflow 每日构建内嵌 quay.io 镜像的容器，加快本地启动速度。</li><li><strong>局限性</strong>：OSD 不由 Cephadm 管理（目录挂载方式）；NVMe/SPDK 服务不可用；多节点场景涉及网络配置较复杂。</li><li><strong>价值</strong>：适合快速开发测试，可做集群状态快照（commit 保存运行中的集群）以实现可复现的测试环境。</li></ul><p>Ernest 补充了 ceph-devstack 项目（Zack Sersa 发起）的相关背景，该项目也探索了类似方向。</p><h3 id="_5-cephadm-可观测性-serve-loop-状态透出" tabindex="-1">5. Cephadm 可观测性（Serve Loop 状态透出） <a class="header-anchor" href="#_5-cephadm-可观测性-serve-loop-状态透出" aria-label="Permalink to &quot;5. Cephadm 可观测性（Serve Loop 状态透出）&quot;">​</a></h3><p><strong>问题</strong>：用户应用 spec 后，不清楚 Cephadm 当前正在执行哪些操作，只能通过 debug 日志追踪，体验较差。</p><p><strong>计划</strong>（Redouane 提议，Adam 补充）：</p><ul><li>在 serve loop 执行各类操作时，记录当前状态和历史队列（正在做什么、最近做了什么）。</li><li>覆盖场景包括：元数据刷新、daemon 部署/移除、计划任务、OSD draining、OSD memory target 调整、升级流程等。</li><li>提供统一的 CLI 命令（如 <code>ceph orch status</code>）展示操作队列，分为&quot;待执行&quot;和&quot;近期已完成&quot;两部分。</li><li>配套完善 serve loop 文档，说明各步骤的含义和典型耗时。</li><li>为大量同类操作（如升级）预留独立子区块展示。</li><li>计划同步建设 Dashboard UI 支持。</li></ul><h3 id="_6-uca-统一-ceph-管理接口" tabindex="-1">6. UCA（统一 Ceph 管理接口） <a class="header-anchor" href="#_6-uca-统一-ceph-管理接口" aria-label="Permalink to &quot;6. UCA（统一 Ceph 管理接口）&quot;">​</a></h3><p>John 介绍了其开发的 UCA（Unified Ceph Admin）工具：</p><ul><li><strong>功能</strong>：允许从本地桌面通过密钥直接运行 <code>ceph</code> 命令、<code>rados</code> 工具、RGW admin 命令、CephFS top 等，无需登录集群节点。</li><li><strong>亮点</strong>：支持从单个节点管理多个集群。</li><li><strong>现状</strong>：已有 PR，但社区关注度有限；在 CephCon 上曾展示，反馈不一。</li><li><strong>讨论</strong>：寻求社区意见——是否值得合入主库，还是作为独立个人项目维护。</li><li><strong>局限</strong>：要求防火墙不阻断 RADOS 流量；与 Dashboard 多集群管理功能存在一定重叠。</li></ul><h3 id="_7-smb-协议更新-john-更新" tabindex="-1">7. SMB 协议更新（John 更新） <a class="header-anchor" href="#_7-smb-协议更新-john-更新" aria-label="Permalink to &quot;7. SMB 协议更新（John 更新）&quot;">​</a></h3><p><strong>SMB shares backed by RGW</strong>：</p><ul><li>已支持以 RGW 为后端的 SMB 共享，适用于 Windows 应用与 S3 应用混合访问同一数据的场景。</li><li>相关代码已合入 main，将随 Vampire 版本发布，不计划 backport 到 Umbrella。</li></ul><p><strong>SMB 与 NFS 共享同一 CephFS subvolume</strong>：</p><ul><li>功能较复杂，边界情况多，采用渐进式启用策略： <ul><li>通过给 subvolume 打版本化 earmark 标记来标识支持级别。</li><li>分阶段从 hacker level → alpha → beta → stable，用户可主动 opt-in 体验。</li><li>设计文档目前在下游，计划迁移至上游。</li></ul></li><li>与会者建议加强公共 API 的设计评审，避免重蹈 cert manager 集成时接口不对齐的问题。</li></ul><h3 id="_8-secrets-manager-模块" tabindex="-1">8. Secrets Manager 模块 <a class="header-anchor" href="#_8-secrets-manager-模块" aria-label="Permalink to &quot;8. Secrets Manager 模块&quot;">​</a></h3><ul><li>当前 secret manager 的基础实现（以 Mon Key-Value Store 为后端）已合入 main。</li><li>计划添加 HashiCorp Vault 作为另一个后端，供各 manager 模块（Cephadm、Prometheus 等）统一使用。</li><li>与会者提出：cert manager 集成时曾因公共接口设计未对齐导致困难，建议在 secret manager 对外接口定稳前进行专项设计评审，Redouane 回归后可组织专题讨论。</li></ul><h3 id="_9-teuthology-测试优化" tabindex="-1">9. Teuthology 测试优化 <a class="header-anchor" href="#_9-teuthology-测试优化" aria-label="Permalink to &quot;9. Teuthology 测试优化&quot;">​</a></h3><ul><li>持续降低失败/已知问题数量，近期 main 分支情况较 umbrella/tentacle/squid 有所改善。</li><li>计划重组测试套件结构： <ul><li>当前按 smoke/small/world 等粗粒度分类，实际指导意义有限。</li><li>拟改为按 daemon 类型（OSD、MON、MDS、RGW 等）组织测试。</li><li>梳理各类型的现有覆盖情况，补充薄弱环节（如 NFS 测试目前较为基础）。</li></ul></li></ul><h2 id="决定事项与后续行动" tabindex="-1">决定事项与后续行动 <a class="header-anchor" href="#决定事项与后续行动" aria-label="Permalink to &quot;决定事项与后续行动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>议题</th><th>负责人</th><th>计划版本</th></tr></thead><tbody><tr><td>Cephadm 主机操作性能优化</td><td>Adam King</td><td>Vampire</td></tr><tr><td>多架构镜像支持（初步）</td><td>Adam King</td><td>Vampire</td></tr><tr><td>Daemon 并行部署（早期合入）</td><td>Adam King</td><td>Vampire 早期</td></tr><tr><td>Cephadm 容器化（依赖解耦优先）</td><td>Ernest / Nizam</td><td>Vampire</td></tr><tr><td>Serve loop 可观测性</td><td>Redouane（主）/ Adam</td><td>Vampire</td></tr><tr><td>UCA 工具社区意见收集</td><td>John</td><td>待定</td></tr><tr><td>SMB on RGW</td><td>John</td><td>Vampire（已在 main）</td></tr><tr><td>SMB+NFS 共享 subvolume</td><td>John</td><td>渐进式，Vampire 启动</td></tr><tr><td>Secret Manager + Vault 后端</td><td>Red Hat 团队</td><td>Vampire</td></tr><tr><td>Secret Manager 公共 API 设计评审</td><td>待 Redouane 回归后组织</td><td>Vampire</td></tr><tr><td>Teuthology 测试重组</td><td>Red Hat 团队</td><td>Vampire</td></tr></tbody></table>',41)])])}const u=t(l,[["render",i]]);export{c as __pageData,u as default};
